1	/* ============================ Người treo dù: trang bị bằng code ============================
2	   Một BufferGeometry có xương (skinIndex / skinWeight) cho SkinnedMesh: đai ngồi, ba lô + hộp dù dự phòng, đai vai / ngực / đùi, khóa, carabiner, riser, quai phanh, dây phanh, dây treo.
3	   Mỗi đỉnh gắn cứng một xương (trọng số 1). Dây và đai nối hai xương là lăng trụ có đáy một xương, đỉnh một xương nên hai đầu luôn bám dù lẫn người khi xương dịch chuyển.
4	   Hệ tọa độ: hệ group dù (+X bay, +Y lên, +Z phải); mọi bộ phận dựng theo vị trí nghỉ của xương truyền vào (PlGearRest), không có số tuyệt đối.
5	   Thuần BufferGeometry, không cần DOM nên test node dùng được. Thông số: CONFIG.explore.pilot.gear. */
6	import * as THREE from 'three';
7	import { CONFIG } from '../../config';
8	import { exLineTops, exBrakeTops } from '../glider';
9	
10	/* Thứ tự xương = giá trị skinIndex. 'wing' là gốc cánh (đầu trên của dây), 'pack' là ba lô lệch pha với thân */
11	export const PL_GEAR_BONES = ['wing', 'hang', 'pelvis', 'spine', 'handL', 'handR', 'thighL', 'thighR', 'pack'] as const;
12	/* Đoạn đỉnh của một dây trong geometry: kind 'line' (dây treo) hoặc 'brake' (nhánh dây phanh); ba / bb = xương hai đầu; geometry.userData.spans */
13	export interface PlGearSpan { kind: 'line' | 'brake'; ba: number; bb: number; start: number; count: number }
14	export interface PlGearRest { hang: number[]; pelvis: number[]; spine: number[]; handL: number[]; handR: number[]; thighL: number[]; thighR: number[] }   // vị trí nghỉ từng xương trong hệ group dù, m
15	
16	const PG = CONFIG.explore.pilot, GC = PG.gear;
17	const BI = (n: typeof PL_GEAR_BONES[number]): number => PL_GEAR_BONES.indexOf(n);
18	const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
19	const COL = (hex: string): number[] => { const c = new THREE.Color(hex); return [c.r, c.g, c.b]; };
20	
21	/* Bộ gom đỉnh không chỉ số: mỗi tam giác có pháp tuyến phẳng, màu và xương theo đỉnh */
22	class GearBuf {
23	  pos: number[] = []; nor: number[] = []; col: number[] = []; si: number[] = [];
24	  spans: PlGearSpan[] = [];   // đoạn đỉnh của từng dây (test dùng để kiểm hai đầu hai xương)
25	  /* Chạy f rồi ghi lại đoạn đỉnh nó sinh ra: dây treo / nhánh dây phanh */
26	  span(kind: PlGearSpan['kind'], ba: number, bb: number, f: () => void): void {
27	    const start = this.si.length; f(); this.spans.push({ kind, ba, bb, start, count: this.si.length - start });
28	  }
29	  /* Một tam giác; ba xương theo ba đỉnh */
30	  tri(a: THREE.Vector3, b: THREE.Vector3, c: THREE.Vector3, ba: number, bb: number, bc: number, rgb: number[]): void {
31	    const n = b.clone().sub(a).cross(c.clone().sub(a));
32	    if (n.lengthSq() < 1e-14) return;
33	    n.normalize();
34	    for (const [p, bone] of [[a, ba], [b, bb], [c, bc]] as [THREE.Vector3, number][]) {
35	      this.pos.push(p.x, p.y, p.z); this.nor.push(n.x, n.y, n.z); this.col.push(rgb[0], rgb[1], rgb[2]); this.si.push(bone);
36	    }
37	  }
38	  /* Mặt bốn đỉnh; ref nằm bên trong khối, mặt luôn quay ra xa ref */
39	  quad(p: THREE.Vector3[], bn: number[], rgb: number[], ref: THREE.Vector3): void {
40	    const ctr = p[0].clone().add(p[1]).add(p[2]).add(p[3]).multiplyScalar(0.25);
41	    const n = p[1].clone().sub(p[0]).cross(p[2].clone().sub(p[0]));
42	    const o = n.dot(ctr.sub(ref)) < 0 ? [0, 3, 2, 1] : [0, 1, 2, 3];
43	    this.tri(p[o[0]], p[o[1]], p[o[2]], bn[o[0]], bn[o[1]], bn[o[2]], rgb);
44	    this.tri(p[o[0]], p[o[2]], p[o[3]], bn[o[0]], bn[o[2]], bn[o[3]], rgb);
45	  }
46	  /* Hộp theo trục tọa độ, tâm c, nửa kích thước h, một xương */
47	  box(c: THREE.Vector3, h: number[], bone: number, rgb: number[]): void {
48	    for (let ax = 0; ax < 3; ax++) {
49	      const u = (ax + 1) % 3, v = (ax + 2) % 3;
50	      for (const sg of [-1, 1]) {
51	        const q: THREE.Vector3[] = [];
52	        for (const [su, sv] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) {
53	          const o = [0, 0, 0]; o[ax] = sg * h[ax]; o[u] = su * h[u]; o[v] = sv * h[v];
54	          q.push(V(c.x + o[0], c.y + o[1], c.z + o[2]));
55	        }
56	        this.quad(q, [bone, bone, bone, bone], rgb, c);
57	      }
58	    }
59	  }
60	  /* Lăng trụ bốn cạnh từ a tới b: mặt cắt w × t, w dọc theo hint (đã chiếu vuông góc trục); đáy a gắn xương ba, đáy b gắn xương bb. Dây: w = t = 2·bán kính */
61	  prism(a: THREE.Vector3, b: THREE.Vector3, ba: number, bb: number, rgb: number[], w: number, t: number, hint = V(0, 0, 1)): void {
62	    const d = b.clone().sub(a);
63	    if (d.length() < 1e-4) return;
64	    d.normalize();
65	    let u = hint.clone().sub(d.clone().multiplyScalar(hint.dot(d)));
66	    if (u.lengthSq() < 1e-6) u = Math.abs(d.y) < 0.9 ? V(0, 1, 0).sub(d.clone().multiplyScalar(d.y)) : V(1, 0, 0).sub(d.clone().multiplyScalar(d.x));
67	    u.normalize();
68	    const v = d.clone().cross(u).normalize();
69	    const ring = (o: THREE.Vector3) => [[1, 1], [-1, 1], [-1, -1], [1, -1]].map(([s, r]) => o.clone().addScaledVector(u, s * w / 2).addScaledVector(v, r * t / 2));
70	    const ra = ring(a), rb = ring(b), ref = a.clone().add(b).multiplyScalar(0.5);
71	    for (let k = 0; k < 4; k++) this.quad([ra[k], ra[(k + 1) % 4], rb[(k + 1) % 4], rb[k]], [ba, ba, bb, bb], rgb, ref);
72	  }
73	  geometry(): THREE.BufferGeometry {
74	    const g = new THREE.BufferGeometry(), n = this.si.length;
75	    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
76	    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nor, 3));
77	    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
78	    const idx = new Uint16Array(n * 4), wt = new Float32Array(n * 4);
79	    for (let i = 0; i < n; i++) { idx[i * 4] = this.si[i]; wt[i * 4] = 1; }
80	    g.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(idx, 4));
81	    g.setAttribute('skinWeight', new THREE.Float32BufferAttribute(wt, 4));
82	    g.userData.spans = this.spans;
83	    return g;
84	  }
85	}
86	
87	/* Dựng toàn bộ trang bị quanh các vị trí nghỉ của xương */
88	export function plGearGeometry(rest: PlGearRest): THREE.BufferGeometry {
89	  const b = new GearBuf(), C = GC.colors, bd = GC.body, gap = GC.gap, sc = GC.seat, bk = GC.back, cs = GC.chest, rv = GC.reserve, tr = GC.thighRing;
90	  const harness = COL(C.harness), strap = COL(C.strap), pack = COL(C.pack), toggle = COL(C.toggle), line = COL(C.line), metal = COL(C.metal), red = COL(C.reserve);
91	  const H = rest.hang, Pl = rest.pelvis, S = rest.spine;
92	  const bone = { wing: BI('wing'), hang: BI('hang'), pel: BI('pelvis'), spine: BI('spine'), pack: BI('pack') };
93	  const tc = S[0], py = Pl[1];                              // tâm thân theo X, cao độ hông
94	  const backX = tc - bd.chestDepth / 2 - gap, frontX = tc + bd.chestDepth / 2 + gap;   // mặt lưng / mặt ngực cộng khe hở
95	  const sz = bd.shoulderHalf - cs.shoulderInset, W = GC.strapW, T = GC.strapT, X = V(1, 0, 0), Y = V(0, 1, 0), Z = V(0, 0, 1);
96	
97	  /* Đai ngồi kiểu ghế: tấm ngồi, hai má hông, tấm lưng dưới (hông) và trên (cột sống) */
98	  b.box(V(Pl[0] + sc.x, py + sc.y, 0), [sc.hx, sc.hy, bd.hipWidth / 2 + sc.zExtra], bone.pel, harness);
99	  for (const s of [-1, 1]) b.box(V(Pl[0] + sc.cheekX, py + sc.cheekY, s * (bd.hipWidth / 2 + gap + sc.cheekZ)), sc.cheekH, bone.pel, harness);
100	  b.box(V(backX + bk.x, py + bk.lowY, 0), bk.lowH, bone.pel, harness);
101	  b.box(V(backX + bk.x, py + bk.upY, 0), bk.upH, bone.spine, harness);
102	
103	  /* Ba lô sau lưng (xương pack lệch pha), hộp dù dự phòng dưới ghế, quai kéo dù dự phòng màu đỏ */
104	  const gp = GC.pack;
105	  b.box(V(backX - bk.packX - gp.depth / 2, py + bk.lowY + gp.height / 2, 0), [gp.depth / 2, gp.height / 2, gp.width / 2], bone.pack, pack);
106	  b.box(V(Pl[0] + rv.x, py + rv.y - gp.reserveH / 2, 0), [rv.hx, gp.reserveH / 2, rv.hz], bone.pack, pack);
107	  const ry = py + rv.y - gp.reserveH / 2;
108	  b.prism(V(Pl[0], ry, rv.hz), V(Pl[0] + rv.pull[0], ry, rv.pull[1]), bone.pack, bone.pack, red, rv.pullW, rv.pullT, Y);
109	  b.box(V(Pl[0] + rv.pull[2], ry, rv.pull[3]), rv.pullH, bone.pack, red);
110	
111	  /* Đai vai: từ lưng qua vai, xuống ngực, tới mép trước ghế; đai nối từ vai tới carabiner */
112	  for (const s of [-1, 1]) {
113	    const back = V(backX, py + bd.shoulderUp - cs.backDrop, s * sz), top = V(tc, py + bd.shoulderUp + cs.topRise + gap, s * sz), front = V(frontX, py + cs.y, s * sz);
114	    const seatF = V(Pl[0] + sc.strapX, py + sc.strapY, s * (bd.hipWidth / 2 - sc.strapZ));
115	    b.prism(back, top, bone.spine, bone.spine, strap, W, T, Z);
116	    b.prism(top, front, bone.spine, bone.spine, strap, W, T, Z);
117	    b.prism(front, seatF, bone.spine, bone.pel, strap, W, T, Z);
118	    /* Carabiner: khung chữ nhật trong mặt phẳng X-Y ở điểm treo, gắn đai ngồi; riser từ móc lên điểm tụ dây (đầu trên gắn xương hang) */
119	    const c = V(H[0], H[1], s * PG.hang.half), cw = GC.carab.w / 2, ch = GC.carab.h / 2, cb = GC.carab.bar;
120	    const k = [V(c.x + cw, c.y + ch, c.z), V(c.x - cw, c.y + ch, c.z), V(c.x - cw, c.y - ch, c.z), V(c.x + cw, c.y - ch, c.z)];
121	    for (let i = 0; i < 4; i++) b.prism(k[i], k[(i + 1) % 4], bone.pel, bone.pel, metal, cb, cb);
122	    b.prism(top, V(c.x - cw, c.y + ch, c.z), bone.spine, bone.pel, strap, W, T, Z);
123	    const riserTop = V(c.x, c.y + PG.riser, c.z);
124	    b.prism(V(c.x, c.y + ch, c.z), riserTop, bone.pel, bone.hang, strap, W * 0.8, T, X);
125	    /* Dây treo: lineCount dây từ đầu riser lên cánh */
126	    for (const t of exLineTops()) if (t.side === s) b.span('line', bone.hang, bone.wing, () => b.prism(riserTop, V(t.x, t.y, t.z), bone.hang, bone.wing, line, GC.lineR * 2, GC.lineR * 2));
127	  }
128	
129	  /* Đai ngực (hai nửa, chừa khe cho khóa) + khóa kim loại */
130	  for (const s of [-1, 1]) b.prism(V(frontX + cs.x, py + cs.y, s * sz), V(frontX + cs.x, py + cs.y, s * cs.gapHalf), bone.spine, bone.spine, strap, W * 0.8, T, Y);
131	  b.box(V(frontX + cs.buckleX, py + cs.y, 0), cs.buckleH, bone.spine, metal);
132	
133	  /* Đai đùi: vòng tám cạnh quanh đùi (gắn xương đùi), đai nối tới mép ghế, khóa ở phía trên */
134	  for (const s of [-1, 1]) {
135	    const Tg = s < 0 ? rest.thighL : rest.thighR, bt = BI(s < 0 ? 'thighL' : 'thighR');
136	    const r = bd.thighR + gap + T, cx = Tg[0] + tr.x, cy = Tg[1] + tr.y, cz = Tg[2];
137	    const ring: THREE.Vector3[] = [];
138	    for (let i = 0; i < 8; i++) { const an = i * Math.PI / 4; ring.push(V(cx, cy + r * Math.cos(an), cz + r * Math.sin(an))); }
139	    for (let i = 0; i < 8; i++) b.prism(ring[i], ring[(i + 1) % 8], bt, bt, strap, W, T, X);
140	    b.prism(V(Pl[0] + tr.strapX, py + tr.strapY, s * (bd.hipWidth / 2 + tr.strapZ)), V(cx, cy + r * 0.7071, cz + s * r * 0.7071), bone.pel, bt, strap, W, T, Y);
141	    b.box(V(cx, cy + r + tr.buckleLift, cz), tr.buckleH, bt, metal);
142	  }
143	
144	  /* Quai phanh ×2 gắn xương bàn tay; dây phanh tụ về một điểm trên quai rồi chia ba nhánh lên mép sau cánh */
145	  for (const s of [-1, 1]) {
146	    const hd = s < 0 ? rest.handL : rest.handR, bh = BI(s < 0 ? 'handL' : 'handR');
147	    const hp = V(hd[0], hd[1], hd[2]), join = V(hd[0], hd[1] + GC.brakeJoin, hd[2]);
148	    b.prism(V(hd[0], hd[1], hd[2] - GC.toggleLen), V(hd[0], hd[1], hd[2] + GC.toggleLen), bh, bh, toggle, GC.toggleW, GC.toggleW);
149	    b.prism(hp, join, bh, bh, line, GC.lineR * 2, GC.lineR * 2);
150	    for (const t of exBrakeTops()) if (t.side === s) b.span('brake', bh, bone.wing, () => b.prism(join, V(t.x, t.y, t.z), bh, bone.wing, line, GC.lineR * 2, GC.lineR * 2));
151	  }
152	  return b.geometry();
153	}
154	
155	/* Vật liệu dùng chung: màu theo đỉnh, nhám, không kim loại để cả trang bị vẫn 1 lệnh vẽ. DoubleSide vì đai và dây là lăng trụ không nắp */
156	let plGearMat: THREE.MeshStandardMaterial | null = null;
157	export function plGearMaterial(): THREE.MeshStandardMaterial {
158	  return plGearMat ??= new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.75, metalness: 0.1, side: THREE.DoubleSide });
159	}
