/* ============================ Người treo dù: trang bị bằng code ============================
   Một BufferGeometry có xương (skinIndex / skinWeight) cho SkinnedMesh: đai ngồi, ba lô + hộp dù dự phòng, đai vai / ngực / đùi, khóa, carabiner, riser, quai phanh, dây phanh, dây treo.
   Mỗi đỉnh gắn cứng một xương (trọng số 1). Dây và đai nối hai xương là lăng trụ có đáy một xương, đỉnh một xương nên hai đầu luôn bám dù lẫn người khi xương dịch chuyển.
   Hệ tọa độ: hệ group dù (+X bay, +Y lên, +Z phải); mọi bộ phận dựng theo vị trí nghỉ của xương truyền vào (PlGearRest), không có số tuyệt đối.
   Thuần BufferGeometry, không cần DOM nên test node dùng được. Thông số: CONFIG.explore.pilot.gear. */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { exLineTops, exBrakeTops } from '../glider';

/* Thứ tự xương = giá trị skinIndex. 'wing' là gốc cánh (đầu trên của dây), 'pack' là ba lô lệch pha với thân */
export const PL_GEAR_BONES = ['wing', 'hang', 'pelvis', 'spine', 'handL', 'handR', 'thighL', 'thighR', 'pack'] as const;
/* Đoạn đỉnh của một dây trong geometry: kind 'line' (dây treo) hoặc 'brake' (nhánh dây phanh); ba / bb = xương hai đầu; geometry.userData.spans */
export interface PlGearSpan { kind: 'line' | 'brake'; ba: number; bb: number; start: number; count: number }
export interface PlGearRest { hang: number[]; pelvis: number[]; spine: number[]; handL: number[]; handR: number[]; thighL: number[]; thighR: number[] }   // vị trí nghỉ từng xương trong hệ group dù, m

const PG = CONFIG.explore.pilot, GC = PG.gear;
const BI = (n: typeof PL_GEAR_BONES[number]): number => PL_GEAR_BONES.indexOf(n);
const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
const COL = (hex: string): number[] => { const c = new THREE.Color(hex); return [c.r, c.g, c.b]; };

/* Bộ gom đỉnh không chỉ số: mỗi tam giác có pháp tuyến phẳng, màu và xương theo đỉnh */
class GearBuf {
  pos: number[] = []; nor: number[] = []; col: number[] = []; si: number[] = [];
  spans: PlGearSpan[] = [];   // đoạn đỉnh của từng dây (test dùng để kiểm hai đầu hai xương)
  /* Chạy f rồi ghi lại đoạn đỉnh nó sinh ra: dây treo / nhánh dây phanh */
  span(kind: PlGearSpan['kind'], ba: number, bb: number, f: () => void): void {
    const start = this.si.length; f(); this.spans.push({ kind, ba, bb, start, count: this.si.length - start });
  }
  /* Một tam giác; ba xương theo ba đỉnh */
  tri(a: THREE.Vector3, b: THREE.Vector3, c: THREE.Vector3, ba: number, bb: number, bc: number, rgb: number[]): void {
    const n = b.clone().sub(a).cross(c.clone().sub(a));
    if (n.lengthSq() < 1e-14) return;
    n.normalize();
    for (const [p, bone] of [[a, ba], [b, bb], [c, bc]] as [THREE.Vector3, number][]) {
      this.pos.push(p.x, p.y, p.z); this.nor.push(n.x, n.y, n.z); this.col.push(rgb[0], rgb[1], rgb[2]); this.si.push(bone);
    }
  }
  /* Mặt bốn đỉnh; ref nằm bên trong khối, mặt luôn quay ra xa ref */
  quad(p: THREE.Vector3[], bn: number[], rgb: number[], ref: THREE.Vector3): void {
    const ctr = p[0].clone().add(p[1]).add(p[2]).add(p[3]).multiplyScalar(0.25);
    const n = p[1].clone().sub(p[0]).cross(p[2].clone().sub(p[0]));
    const o = n.dot(ctr.sub(ref)) < 0 ? [0, 3, 2, 1] : [0, 1, 2, 3];
    this.tri(p[o[0]], p[o[1]], p[o[2]], bn[o[0]], bn[o[1]], bn[o[2]], rgb);
    this.tri(p[o[0]], p[o[2]], p[o[3]], bn[o[0]], bn[o[2]], bn[o[3]], rgb);
  }
  /* Hộp theo trục tọa độ, tâm c, nửa kích thước h, một xương */
  box(c: THREE.Vector3, h: number[], bone: number, rgb: number[]): void {
    for (let ax = 0; ax < 3; ax++) {
      const u = (ax + 1) % 3, v = (ax + 2) % 3;
      for (const sg of [-1, 1]) {
        const q: THREE.Vector3[] = [];
        for (const [su, sv] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) {
          const o = [0, 0, 0]; o[ax] = sg * h[ax]; o[u] = su * h[u]; o[v] = sv * h[v];
          q.push(V(c.x + o[0], c.y + o[1], c.z + o[2]));
        }
        this.quad(q, [bone, bone, bone, bone], rgb, c);
      }
    }
  }
  /* Lăng trụ bốn cạnh từ a tới b: mặt cắt w × t, w dọc theo hint (đã chiếu vuông góc trục); đáy a gắn xương ba, đáy b gắn xương bb. Dây: w = t = 2·bán kính */
  prism(a: THREE.Vector3, b: THREE.Vector3, ba: number, bb: number, rgb: number[], w: number, t: number, hint = V(0, 0, 1)): void {
    const d = b.clone().sub(a);
    if (d.length() < 1e-4) return;
    d.normalize();
    let u = hint.clone().sub(d.clone().multiplyScalar(hint.dot(d)));
    if (u.lengthSq() < 1e-6) u = Math.abs(d.y) < 0.9 ? V(0, 1, 0).sub(d.clone().multiplyScalar(d.y)) : V(1, 0, 0).sub(d.clone().multiplyScalar(d.x));
    u.normalize();
    const v = d.clone().cross(u).normalize();
    const ring = (o: THREE.Vector3) => [[1, 1], [-1, 1], [-1, -1], [1, -1]].map(([s, r]) => o.clone().addScaledVector(u, s * w / 2).addScaledVector(v, r * t / 2));
    const ra = ring(a), rb = ring(b), ref = a.clone().add(b).multiplyScalar(0.5);
    for (let k = 0; k < 4; k++) this.quad([ra[k], ra[(k + 1) % 4], rb[(k + 1) % 4], rb[k]], [ba, ba, bb, bb], rgb, ref);
  }
  geometry(): THREE.BufferGeometry {
    const g = new THREE.BufferGeometry(), n = this.si.length;
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nor, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
    const idx = new Uint16Array(n * 4), wt = new Float32Array(n * 4);
    for (let i = 0; i < n; i++) { idx[i * 4] = this.si[i]; wt[i * 4] = 1; }
    g.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(idx, 4));
    g.setAttribute('skinWeight', new THREE.Float32BufferAttribute(wt, 4));
    g.userData.spans = this.spans;
    return g;
  }
}

/* Dựng toàn bộ trang bị quanh các vị trí nghỉ của xương */
export function plGearGeometry(rest: PlGearRest): THREE.BufferGeometry {
  const b = new GearBuf(), C = GC.colors, bd = GC.body, gap = GC.gap, sc = GC.seat, bk = GC.back, cs = GC.chest, rv = GC.reserve, tr = GC.thighRing;
  const harness = COL(C.harness), strap = COL(C.strap), pack = COL(C.pack), toggle = COL(C.toggle), line = COL(C.line), metal = COL(C.metal), red = COL(C.reserve);
  const H = rest.hang, Pl = rest.pelvis, S = rest.spine;
  const bone = { wing: BI('wing'), hang: BI('hang'), pel: BI('pelvis'), spine: BI('spine'), pack: BI('pack') };
  const tc = S[0], py = Pl[1];                              // tâm thân theo X, cao độ hông
  const backX = tc - bd.chestDepth / 2 - gap, frontX = tc + bd.chestDepth / 2 + gap;   // mặt lưng / mặt ngực cộng khe hở
  const sz = bd.shoulderHalf - cs.shoulderInset, W = GC.strapW, T = GC.strapT, X = V(1, 0, 0), Y = V(0, 1, 0), Z = V(0, 0, 1);

  /* Đai ngồi kiểu ghế: tấm ngồi, hai má hông, tấm lưng dưới (hông) và trên (cột sống) */
  b.box(V(Pl[0] + sc.x, py + sc.y, 0), [sc.hx, sc.hy, bd.hipWidth / 2 + sc.zExtra], bone.pel, harness);
  for (const s of [-1, 1]) b.box(V(Pl[0] + sc.cheekX, py + sc.cheekY, s * (bd.hipWidth / 2 + gap + sc.cheekZ)), sc.cheekH, bone.pel, harness);
  b.box(V(backX + bk.x, py + bk.lowY, 0), bk.lowH, bone.pel, harness);
  b.box(V(backX + bk.x, py + bk.upY, 0), bk.upH, bone.spine, harness);

  /* Ba lô sau lưng (xương pack lệch pha), hộp dù dự phòng dưới ghế, quai kéo dù dự phòng màu đỏ */
  const gp = GC.pack;
  b.box(V(backX - bk.packX - gp.depth / 2, py + bk.lowY + gp.height / 2, 0), [gp.depth / 2, gp.height / 2, gp.width / 2], bone.pack, pack);
  b.box(V(Pl[0] + rv.x, py + rv.y - gp.reserveH / 2, 0), [rv.hx, gp.reserveH / 2, rv.hz], bone.pack, pack);
  const ry = py + rv.y - gp.reserveH / 2;
  b.prism(V(Pl[0], ry, rv.hz), V(Pl[0] + rv.pull[0], ry, rv.pull[1]), bone.pack, bone.pack, red, rv.pullW, rv.pullT, Y);
  b.box(V(Pl[0] + rv.pull[2], ry, rv.pull[3]), rv.pullH, bone.pack, red);

  /* Đai vai: từ lưng qua vai, xuống ngực, tới mép trước ghế; đai nối từ vai tới carabiner */
  for (const s of [-1, 1]) {
    const back = V(backX, py + bd.shoulderUp - cs.backDrop, s * sz), top = V(tc, py + bd.shoulderUp + cs.topRise + gap, s * sz), front = V(frontX, py + cs.y, s * sz);
    const seatF = V(Pl[0] + sc.strapX, py + sc.strapY, s * (bd.hipWidth / 2 - sc.strapZ));
    b.prism(back, top, bone.spine, bone.spine, strap, W, T, Z);
    b.prism(top, front, bone.spine, bone.spine, strap, W, T, Z);
    b.prism(front, seatF, bone.spine, bone.pel, strap, W, T, Z);
    /* Carabiner: khung chữ nhật trong mặt phẳng X-Y ở điểm treo, gắn đai ngồi; riser từ móc lên điểm tụ dây (đầu trên gắn xương hang) */
    const c = V(H[0], H[1], s * PG.hang.half), cw = GC.carab.w / 2, ch = GC.carab.h / 2, cb = GC.carab.bar;
    const k = [V(c.x + cw, c.y + ch, c.z), V(c.x - cw, c.y + ch, c.z), V(c.x - cw, c.y - ch, c.z), V(c.x + cw, c.y - ch, c.z)];
    for (let i = 0; i < 4; i++) b.prism(k[i], k[(i + 1) % 4], bone.pel, bone.pel, metal, cb, cb);
    b.prism(top, V(c.x - cw, c.y + ch, c.z), bone.spine, bone.pel, strap, W, T, Z);
    const riserTop = V(c.x, c.y + PG.riser, c.z);
    b.prism(V(c.x, c.y + ch, c.z), riserTop, bone.pel, bone.hang, strap, W * 0.8, T, X);
    /* Dây treo: lineCount dây từ đầu riser lên cánh */
    for (const t of exLineTops()) if (t.side === s) b.span('line', bone.hang, bone.wing, () => b.prism(riserTop, V(t.x, t.y, t.z), bone.hang, bone.wing, line, GC.lineR * 2, GC.lineR * 2));
  }

  /* Đai ngực (hai nửa, chừa khe cho khóa) + khóa kim loại */
  for (const s of [-1, 1]) b.prism(V(frontX + cs.x, py + cs.y, s * sz), V(frontX + cs.x, py + cs.y, s * cs.gapHalf), bone.spine, bone.spine, strap, W * 0.8, T, Y);
  b.box(V(frontX + cs.buckleX, py + cs.y, 0), cs.buckleH, bone.spine, metal);

  /* Đai đùi: vòng tám cạnh quanh đùi (gắn xương đùi), đai nối tới mép ghế, khóa ở phía trên */
  for (const s of [-1, 1]) {
    const Tg = s < 0 ? rest.thighL : rest.thighR, bt = BI(s < 0 ? 'thighL' : 'thighR');
    const r = bd.thighR + gap + T, cx = Tg[0] + tr.x, cy = Tg[1] + tr.y, cz = Tg[2];
    const ring: THREE.Vector3[] = [];
    for (let i = 0; i < 8; i++) { const an = i * Math.PI / 4; ring.push(V(cx, cy + r * Math.cos(an), cz + r * Math.sin(an))); }
    for (let i = 0; i < 8; i++) b.prism(ring[i], ring[(i + 1) % 8], bt, bt, strap, W, T, X);
    b.prism(V(Pl[0] + tr.strapX, py + tr.strapY, s * (bd.hipWidth / 2 + tr.strapZ)), V(cx, cy + r * 0.7071, cz + s * r * 0.7071), bone.pel, bt, strap, W, T, Y);
    b.box(V(cx, cy + r + tr.buckleLift, cz), tr.buckleH, bt, metal);
  }

  /* Quai phanh ×2 gắn xương bàn tay; dây phanh tụ về một điểm trên quai rồi chia ba nhánh lên mép sau cánh */
  for (const s of [-1, 1]) {
    const hd = s < 0 ? rest.handL : rest.handR, bh = BI(s < 0 ? 'handL' : 'handR');
    const hp = V(hd[0], hd[1], hd[2]), join = V(hd[0], hd[1] + GC.brakeJoin, hd[2]);
    b.prism(V(hd[0], hd[1], hd[2] - GC.toggleLen), V(hd[0], hd[1], hd[2] + GC.toggleLen), bh, bh, toggle, GC.toggleW, GC.toggleW);
    b.prism(hp, join, bh, bh, line, GC.lineR * 2, GC.lineR * 2);
    for (const t of exBrakeTops()) if (t.side === s) b.span('brake', bh, bone.wing, () => b.prism(join, V(t.x, t.y, t.z), bh, bone.wing, line, GC.lineR * 2, GC.lineR * 2));
  }
  return b.geometry();
}

/* Vật liệu dùng chung: màu theo đỉnh, nhám, không kim loại để cả trang bị vẫn 1 lệnh vẽ. DoubleSide vì đai và dây là lăng trụ không nắp */
let plGearMat: THREE.MeshStandardMaterial | null = null;
export function plGearMaterial(): THREE.MeshStandardMaterial {
  return plGearMat ??= new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.75, metalness: 0.1, side: THREE.DoubleSide });
}

content.content:
1	/* ============================ Tự khám phá: mô hình dù lượn ============================
2	   Một Mesh duy nhất (cánh vòm in cờ đỏ sao vàng + dây + người treo + dải đèn mép cánh), gộp bằng mergeGeometries, vertex color nhân với atlas canvas.
3	   Hệ cục bộ: +X là hướng bay, +Y lên, +Z bên phải. Atlas: phần trên là mặt cánh, dải dưới là màu trơn; emissiveMap cùng bố cục, cường độ đọc shared.uNight.
4	   Mọi thông số nằm ở CONFIG.explore.glider (span, lines = khoảng treo, lineCount, chord, arch, segs). */
5	import * as THREE from 'three';
6	import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
7	import { CONFIG } from '../config';
8	import { shared } from '../core/shared';
9	import type { GliderState, GliderInput } from './flight';
10	
11	const G = CONFIG.explore.glider;
12	const UV_DARK = 0.25, UV_LIT = 0.75;         // u trong dải màu trơn: nửa tối / nửa sáng
13	const TILT = Math.tan(G.tilt);               // độ dốc cánh theo hướng bay (mép sau thấp hơn)
14	const ATLAS_W = 1024, ATLAS_H = 256;         // điểm ảnh atlas
15	const WING_H = 216, BAND_Y = 224;            // mặt cánh chiếm y 0..WING_H; dải màu trơn từ BAND_Y tới đáy; khoảng giữa để đệm
16	const V_SOLID = 1 - (BAND_Y + ATLAS_H) / 2 / ATLAS_H, V_WING0 = 1 - WING_H / ATLAS_H;   // v giữa dải màu trơn; v của mép sau cánh
17	
18	/* Gán uv và màu đỉnh cho hình học không chỉ số */
19	function exPaint(g: THREE.BufferGeometry, rgb: number[], u: number): THREE.BufferGeometry {
20	  const n = g.attributes.position.count, col = new Float32Array(n * 3), uv = new Float32Array(n * 2);
21	  for (let i = 0; i < n; i++) { col.set(rgb, i * 3); uv[i * 2] = u; uv[i * 2 + 1] = V_SOLID; }
22	  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
23	  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
24	  return g;
25	}
26	
27	/* Dải cánh vòm giữa hai mặt cắt: lệch x0..x1 theo hướng bay, cong xuống ở hai đầu */
28	function exWingStrip(chord0: number, chord1: number, rgb: number[], u: number, lift: number): THREE.BufferGeometry {
29	  const pos: number[] = [];
30	  const half = G.span / 2;
31	  for (let i = 0; i < G.segs; i++) {
32	    const ta = -1 + 2 * i / G.segs, tb = -1 + 2 * (i + 1) / G.segs;
33	    const pa = (t: number, x: number) => [x, -G.arch * half * t * t + lift + x * TILT, t * half];
34	    const a0 = pa(ta, chord0), a1 = pa(ta, chord1), b0 = pa(tb, chord0), b1 = pa(tb, chord1);
35	    pos.push(...a0, ...b0, ...a1, ...a1, ...b0, ...b1);
36	  }
37	  const g = new THREE.BufferGeometry();
38	  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
39	  g.computeVertexNormals();
40	  return exPaint(g, rgb, u);
41	}
42	
43	/* Điểm theo hệ người treo: y tính từ móc treo (−G.lines) */
44	const exP = (x: number, y: number, z: number) => new THREE.Vector3(x, y - G.lines, z);
45	
46	/* Khối bo tròn nối hai điểm (tay, chân, thân) */
47	function exLimb(a: THREE.Vector3, b: THREE.Vector3, r: number, rgb: number[]): THREE.BufferGeometry {
48	  const d = b.clone().sub(a), len = d.length();
49	  const g = new THREE.CapsuleGeometry(r, len, 3, 8).toNonIndexed();
50	  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize()));
51	  g.translate((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2);
52	  return exPaint(g, rgb, UV_DARK);
53	}
54	
55	/* Khối elip tại c, bán trục s */
56	function exBlob(c: THREE.Vector3, s: number[], rgb: number[]): THREE.BufferGeometry {
57	  const g = new THREE.SphereGeometry(1, 12, 8).toNonIndexed();
58	  g.scale(s[0], s[1], s[2]); g.translate(c.x, c.y, c.z);
59	  return exPaint(g, rgb, UV_DARK);
60	}
61	
62	/* Người ngồi trong ghế dù, ngả nhẹ ra sau, chân duỗi về trước, tay cầm dây phanh */
63	function exHuman(parts: THREE.BufferGeometry[]): void {
64	  const JACKET = [0.16, 0.3, 0.55], PANTS = [0.12, 0.13, 0.17], SEAT = [0.05, 0.05, 0.07], BOOT = [0.3, 0.17, 0.08], SKIN = [0.86, 0.66, 0.5], HELMET = [0.92, 0.92, 0.9], VISOR = [0.05, 0.06, 0.1];
65	  parts.push(exBlob(exP(-0.22, -0.68, 0), [0.32, 0.2, 0.3], SEAT));                  // ghế dù
66	  parts.push(exBlob(exP(-0.36, -0.28, 0), [0.14, 0.32, 0.26], SEAT));                // lưng ghế, túi dù dự phòng
67	  parts.push(exLimb(exP(-0.08, -0.62, 0), exP(-0.16, -0.12, 0), 0.19, JACKET));      // thân
68	  for (const z of [-1, 1]) {
69	    parts.push(exLimb(exP(0, 0, z * 0.2), exP(-0.12, -0.3, z * 0.22), 0.025, SEAT));  // đai treo từ móc xuống vai
70	    parts.push(exLimb(exP(-0.04, -0.68, z * 0.13), exP(0.4, -0.7, z * 0.17), 0.085, PANTS));   // đùi
71	    parts.push(exLimb(exP(0.4, -0.7, z * 0.17), exP(0.58, -1.08, z * 0.17), 0.065, PANTS));    // cẳng chân
72	    parts.push(exBlob(exP(0.65, -1.14, z * 0.17), [0.14, 0.06, 0.07], BOOT));         // giày
73	    parts.push(exLimb(exP(-0.14, -0.12, z * 0.24), exP(-0.06, -0.08, z * 0.46), 0.06, JACKET));  // cánh tay
74	    parts.push(exLimb(exP(-0.06, -0.08, z * 0.46), exP(0.02, 0.3, z * 0.34), 0.05, JACKET));     // cẳng tay giơ lên
75	    parts.push(exBlob(exP(0.02, 0.34, z * 0.34), [0.05, 0.06, 0.05], SKIN));          // bàn tay
76	  }
77	  parts.push(exBlob(exP(-0.14, 0.17, 0), [0.12, 0.13, 0.11], SKIN));                  // đầu
78	  parts.push(exBlob(exP(-0.16, 0.22, 0), [0.15, 0.13, 0.135], HELMET));               // mũ bảo hiểm
79	  parts.push(exBlob(exP(-0.05, 0.17, 0), [0.05, 0.035, 0.09], VISOR));                // kính
80	}
81	
82	/* Trải mặt cánh lên atlas: u theo sải, v theo dây cung (mép trước ở đỉnh ảnh, nên đỉnh sao hướng về mép trước) */
83	function exWingUv(g: THREE.BufferGeometry): THREE.BufferGeometry {
84	  const p = g.attributes.position, uv = g.attributes.uv as THREE.BufferAttribute;
85	  for (let i = 0; i < p.count; i++) uv.setXY(i, (p.getZ(i) / G.span + 0.5), V_WING0 + (1 - V_WING0) * (p.getX(i) / G.chord + 0.5));
86	  return g;
87	}
88	
89	/* Hộp mảnh nối hai điểm (dây treo) */
90	function exLine(a: THREE.Vector3, b: THREE.Vector3): THREE.BufferGeometry {
91	  const d = b.clone().sub(a), len = d.length();
92	  const g = new THREE.BoxGeometry(0.03, len, 0.03).toNonIndexed();
93	  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize()));
94	  g.translate((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2);
95	  g.deleteAttribute('uv');
96	  return exPaint(g, [0.15, 0.15, 0.15], UV_DARK);
97	}
98	
99	/* Vẽ mặt cánh: nền đỏ, sao vàng 5 cánh một đỉnh hướng lên, đường ô khí. Tính theo mét nên sao không méo. glow: bản phát sáng ban đêm, tối hơn */
100	function exDrawWing(x: CanvasRenderingContext2D, glow: boolean, wingColor?: string): void {
101	  const sx = ATLAS_W / G.span, sy = WING_H / G.chord, cx = ATLAS_W / 2, cy = WING_H / 2;
102	  x.fillStyle = wingColor ?? G.flagRed; x.fillRect(0, 0, ATLAS_W, BAND_Y);
103	  if (!wingColor) {   // dù của mình: cờ đỏ sao vàng; dù người khác chỉ có nền màu
104	    x.beginPath();
105	    for (let i = 0; i < 10; i++) {
106	      const r = G.starRadius * (i % 2 ? 0.382 : 1), a = -Math.PI / 2 + i * Math.PI / 5;
107	      x.lineTo(cx + Math.cos(a) * r * sx, cy + Math.sin(a) * r * sy);
108	    }
109	    x.closePath(); x.fillStyle = G.flagStar; x.fill();
110	  }
111	  x.fillStyle = 'rgba(70,0,0,0.28)';
112	  for (let i = 0; i <= G.cells; i++) x.fillRect(i * ATLAS_W / G.cells - 1, 0, 2, WING_H);
113	  x.fillStyle = 'rgba(70,0,0,0.12)';
114	  for (const k of [0.3, 0.65]) x.fillRect(0, WING_H * k - 1, ATLAS_W, 2);
115	  if (glow) { x.fillStyle = 'rgba(0,0,0,0.62)'; x.fillRect(0, 0, ATLAS_W, BAND_Y); }
116	}
117	
118	function exAtlasTexture(c: HTMLCanvasElement): THREE.CanvasTexture {
119	  const t = new THREE.CanvasTexture(c);
120	  t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4;
121	  return t;
122	}
123	
124	/* Màu cánh: mặt cánh + dải trơn trắng (nhân với vertex color) */
125	function exColorMap(wingColor?: string): THREE.CanvasTexture {
126	  const c = document.createElement('canvas'); c.width = ATLAS_W; c.height = ATLAS_H;
127	  const x = c.getContext('2d')!;
128	  exDrawWing(x, false, wingColor);
129	  x.fillStyle = '#fff'; x.fillRect(0, BAND_Y, ATLAS_W, ATLAS_H - BAND_Y);
130	  return exAtlasTexture(c);
131	}
132	
133	/* Phát sáng ban đêm: cánh sáng dịu để vẫn thấy cờ; dải trơn nửa trái đen, nửa phải trắng */
134	function exGlowMap(wingColor?: string): THREE.CanvasTexture {
135	  const c = document.createElement('canvas'); c.width = ATLAS_W; c.height = ATLAS_H;
136	  const x = c.getContext('2d')!;
137	  exDrawWing(x, true, wingColor);
138	  x.fillStyle = '#000'; x.fillRect(0, BAND_Y, ATLAS_W / 2, ATLAS_H - BAND_Y);
139	  x.fillStyle = '#fff'; x.fillRect(ATLAS_W / 2, BAND_Y, ATLAS_W / 2, ATLAS_H - BAND_Y);
140	  return exAtlasTexture(c);
141	}
142	
143	/* Cánh: mặt chính + dải đèn hai mép (nhô nhẹ lên trên mặt cánh). Dùng chung cho hình 'full' và 'canopy' */
144	function exWingParts(): THREE.BufferGeometry[] {
145	  const parts: THREE.BufferGeometry[] = [];
146	  const body = exWingUv(exWingStrip(-G.chord / 2, G.chord / 2, [1, 1, 1], UV_DARK, 0));
147	  parts.push(body);
148	  parts.push(exWingStrip(G.chord / 2 - 0.12, G.chord / 2, [1, 0.42, 0.38], UV_LIT, 0.02));
149	  parts.push(exWingStrip(-G.chord / 2, -G.chord / 2 + 0.12, [0.75, 0.1, 0.08], UV_LIT, 0.02));   // mép sau: thấy rõ từ camera bám đuôi
150	  return parts;
151	}
152	
153	/* Điểm bám dây thứ i trên cánh ở bên side, trước khi cộng originAt (công thức duy nhất cho dây của hình 'full' lẫn exLineTops): so le trước / sau */
154	function exLineTop(i: number, side: -1 | 1): THREE.Vector3 {
155	  const half = G.span / 2, t = 0.12 + 0.75 * i / Math.max(1, G.lineCount - 1), x = (i % 2 ? 0.5 : -0.5) * G.chord * 0.6;
156	  return new THREE.Vector3(x, -G.arch * half * t * t + x * TILT, side * t * half);
157	}
158	
159	/* Điểm bám dây treo trên cánh (hệ group dù, đã cộng originAt): G.lineCount điểm mỗi bên */
160	export function exLineTops(): { x: number; y: number; z: number; side: -1 | 1 }[] {
161	  const out: { x: number; y: number; z: number; side: -1 | 1 }[] = [];
162	  for (const side of [-1, 1] as const) {
163	    for (let i = 0; i < G.lineCount; i++) { const p = exLineTop(i, side); out.push({ x: p.x, y: p.y + G.lines * G.originAt, z: p.z, side }); }
164	  }
165	  return out;
166	}
167	
168	/* Điểm bám dây phanh trên mép sau cánh (hệ group dù): 3 điểm mỗi bên, trải theo sải từ 0,3 tới 0,8 nửa sải */
169	export function exBrakeTops(): { x: number; y: number; z: number; side: -1 | 1 }[] {
170	  const out: { x: number; y: number; z: number; side: -1 | 1 }[] = [], half = G.span / 2, x = -G.chord / 2;
171	  for (const side of [-1, 1] as const) {
172	    for (const t of [0.3, 0.55, 0.8]) out.push({ x, y: -G.arch * half * t * t + x * TILT + G.lines * G.originAt, z: side * t * half, side });
173	  }
174	  return out;
175	}
176	
177	/* y của điểm treo trong hệ group dù (người treo cách cánh G.lines, gốc group ở tỉ lệ originAt) */
178	export const exHangY = -G.lines * (1 - G.originAt);
179	
180	/* Hình học dùng chung mọi dù (dựng một lần mỗi loại). 'full': cánh + người hình khối + dây (hình tạm khi nhân vật có xương chưa tải); 'canopy': chỉ cánh (người, dây do pilot/gear.ts dựng) */
181	const exGeos: { full: THREE.BufferGeometry | null; canopy: THREE.BufferGeometry | null } = { full: null, canopy: null };
182	const exMaps = new Map<string, { map: THREE.CanvasTexture; glow: THREE.CanvasTexture }>();
183	
184	export function exGliderGeometry(kind: 'full' | 'canopy'): THREE.BufferGeometry {
185	  const cached = exGeos[kind];
186	  if (cached) return cached;
187	  const parts = exWingParts();
188	  if (kind === 'full') {
189	    /* Người treo, cách cánh G.lines mét */
190	    exHuman(parts);
191	    /* Dây: G.lineCount dây mỗi bên, từ cánh xuống vai */
192	    for (const side of [-1, 1] as const) {
193	      for (let i = 0; i < G.lineCount; i++) parts.push(exLine(exLineTop(i, side), new THREE.Vector3(0, -G.lines, side * 0.2)));
194	    }
195	  }
196	  const geo = mergeGeometries(parts)!;
197	  /* Gốc group nằm giữa cánh (trên) và người (dưới): cánh ở +lines·k, người ở −lines·(1−k) */
198	  geo.translate(0, G.lines * G.originAt, 0);
199	  return exGeos[kind] = geo;
200	}
201	
202	/* wingColor bỏ trống: dù cờ đỏ sao vàng của mình. Có wingColor: nền màu đó, không sao, giữ đường ô khí (dù người khác) */
203	export function exBuildGlider(wingColor?: string): THREE.Group {
204	  const geo = exGliderGeometry('full');
205	  const key = wingColor ?? '';
206	  let tex = exMaps.get(key);
207	  if (!tex) exMaps.set(key, tex = { map: exColorMap(wingColor), glow: exGlowMap(wingColor) });
208	  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, map: tex.map, roughness: G.roughness, side: THREE.DoubleSide, emissive: 0xffffff, emissiveMap: tex.glow, emissiveIntensity: 0 });
209	  const mesh = new THREE.Mesh(geo, mat);
210	  mesh.castShadow = false; mesh.receiveShadow = false; mesh.frustumCulled = false;
211	  const g = new THREE.Group(); g.name = 'ex-glider'; g.add(mesh);
212	  return g;
213	}
214	
