1	/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
2	   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
3	   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
4	import * as THREE from 'three';
5	import { scene, camera, controls } from '../core/renderer';
6	import { cam, keys } from '../views/state';
7	import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
8	import { exBuildGlider, exPlaceGlider } from './glider';
9	import { exChase } from './chase';
10	import { exShowChooser } from './chooser';
11	import { exNight, exNightBind, exNightStep } from './nightShows';
12	import { exMulti } from './multi';
13	import { stroll, setupStroll } from './stroll';
14	import { drive, setupDrive } from './drive';
15	import { stAvatars } from './stroll/avatars';
16	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from './multi/watch';
17	import { CONFIG } from '../config';
18	import type { SwingController } from '../bridges/song-han/SwingController';
19	
20	const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung
21	
22	let glider: THREE.Group | null = null;
23	let state: GliderState | null = null;
24	let watching = false;   // đang xem người khác bay (hết chỗ hoặc vừa nhường chỗ): không có dù của mình, không đọc phím
25	let chased = false;     // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
26	let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi
27	
28	const active = () => cam.mode === 'glider' && state !== null;
29	const inGlider = () => active() || watching;   // Esc và giao diện bay áp cho cả chế độ xem
30	
31	/* Mỗi khung khi xem: dù người khác, nhãn, danh sách; camera bám dù đang xem (không có người thì giữ nguyên) */
32	function watchStep(dt: number): void {
33	  exMulti.update(dt, performance.now(), null);
34	  const st = exMulti.watchState();
35	  if (st) { exChase(camera, controls.target, st, dt, !chased); chased = true; }
36	  exNightStep(dt);
37	}
38	
39	/* Đổi phiên khi đang xem hoặc bay: vào bay, mất kết nối, bị thu hồi chỗ */
40	function onMultiChange(): void {
41	  const s = exMulti.session; if (!s) return;
42	  if (watching) {
43	    if (s.phase === 'flying') { explore.start(); return; }   // chấp nhận lời mời: cất cánh mới như bay thường
44	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } explore.exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
45	    exWatchRender();
46	  } else if (active()) {
47	    if (s.phase === 'watching') { state = null; if (glider) glider.visible = false; explore.startWatching(true); return; }   // chỗ bị thu hồi: sang xem, camera giữ nguyên
48	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'exMpLost');   // vẫn bay, người khác đã biến mất
49	  }
50	}
51	
52	/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
53	function exShowSpeed(): void {
54	  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
55	  if (t === readout) return;
56	  readout = t;
57	  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
58	}
59	
60	/* Một bước: mô phỏng, đặt dù, đặt camera bám */
61	function advance(dt: number, inp: GliderInput): void {
62	  exStep(state!, inp, dt);
63	  exPlaceGlider(glider!, state!);
64	  exChase(camera, controls.target, state!, dt);
65	  exShowSpeed();
66	  exNightStep(dt);
67	  exMulti.update(dt, performance.now(), state);   // dù người khác, nhãn tên, gửi vị trí (không làm gì khi bay một mình)
68	}
69	
70	export const explore = {
71	  active,
72	  nightShows: exNight,
73	  get state() { return state; },
74	  get glider() { return glider; },
75	  get watching() { return watching; },
76	  start(): void {
77	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
78	    exMulti.onChange = onMultiChange;
79	    state = exCreate();
80	    const slot = exMulti.session ? exMulti.session.mySlot : -1;
81	    if (slot >= 0) state.pos.z += CONFIG.explore.multi.spawnSpread * (slot - 2);   // mỗi slot cất cánh lệch một đoạn để không chồng nhau
82	    if (!glider) glider = exBuildGlider();
83	    if (!glider.parent) scene.add(glider);
84	    glider.visible = true;
85	    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
86	    exPlaceGlider(glider, state);
87	    exChase(camera, controls.target, state, 0, true);
88	    exShowSpeed();
89	    document.body.classList.add('explore');
90	  },
91	  /* Chế độ xem: cam.mode = 'glider' nhưng không có state/dù của mình; carry = true khi vừa nhường chỗ (camera đang ở sau dù cũ) */
92	  startWatching(carry = false): void {
93	    const s = exMulti.session; if (!s) return;
94	    watching = true; chased = carry;
95	    keys.clear();
96	    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
97	    document.body.classList.add('explore', 'ex-watching');
98	    exMulti.onChange = onMultiChange;
99	    exWatchShow(s);
100	  },
101	  update(dt: number): void {
102	    if (watching) { watchStep(dt); return; }
103	    if (!active()) return;
104	    advance(dt, exInputFromKeys(keys, _inp));
105	  },
106	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
107	  step(dt: number, inp: GliderInput): void {
108	    if (active()) advance(dt, inp);
109	  },
110	  exit(): void {
111	    drive.stop();   // lái xe: trả hầm / lớp body / xe trước khi tải lại
112	    const u = new URL(location.href);
113	    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
114	    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
115	    else location.replace(u.toString());
116	  },
117	};
118	
119	export function setupExplore(ctrl: SwingController): void {
120	  exNightBind(ctrl);
121	  setupStroll(ctrl, () => explore.exit());
122	  setupDrive(ctrl, () => explore.exit());
123	  window.addEventListener('keydown', (e) => {
124	    if (!inGlider() && !stroll.inMode() && !drive.inMode()) return;
125	    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn (bay dù, đi dạo, lái xe và hai chế độ xem)
126	    if (watching || stroll.inMode() || drive.inMode()) return;   // xem: không lái; đi dạo / lái xe: phím do stroll/index.ts, drive/index.ts ghi
127	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
128	    const t = e.target as HTMLElement | null;
129	    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
130	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
131	    const k = e.key.toLowerCase(); keys.add(k);
132	    if (k.startsWith('arrow')) e.preventDefault();
133	  });
134	  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
135	  for (const id of ['langSelect', 'qualitySel']) {
136	    const sel = document.getElementById(id); if (!sel) continue;
137	    let byMouse = false;
138	    sel.addEventListener('pointerdown', () => { byMouse = true; });
139	    sel.addEventListener('keydown', () => { byMouse = false; });
140	    sel.addEventListener('change', () => { if (byMouse && (active() || stroll.active() || drive.active())) sel.blur(); byMouse = false; });
141	  }
142	  const q = new URLSearchParams(location.search);
143	  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
144	  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
145	  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
146	  if (q.get('explore') === 'glider') { explore.start(); return; }
147	  if (q.get('explore') === 'stroll') { stroll.start(); return; }   // đi dạo một mình, không qua slot
148	  if (q.get('explore') === 'drive') { drive.start(); return; }   // lái xe một mình
149	  if (!q.has('test') || q.has('chooser')) {
150	    document.querySelector('button[data-pick="walk"]')?.addEventListener('click', () => stAvatars.preload(0));   // chọn thẻ Đi dạo: nạp nhân vật của mình ngay, trong lúc ở sảnh
151	    document.querySelector('button[data-pick="car"]')?.addEventListener('click', () => drive.preload());   // chọn thẻ Ô tô: nạp mô hình xe ngay
152	    exShowChooser((choice) => { if (choice === 'glider') explore.start(); else if (choice === 'walk') stroll.start(); else if (choice === 'car') drive.start(); },
153	      (choice) => { if (choice === 'walk') stroll.startWatching(); else if (choice === 'car') drive.startWatching(); else explore.startWatching(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
154	  }
155	}
