2	export const shared = { uTime: { value: 0 }, uNight: { value: 0 } };
3	/* Hệ số cỡ hạt lửa / nước theo chiều cao khung hình (cập nhật khi đổi kích thước) */
4	export const pScale = { value: 1 };
5	/* Uniform thời tiết (mặt ướt, mưa, gió, mù nóng, hệ số lắc). TÁCH khỏi `shared` vì MAT.ledRail dùng nguyên object `shared` làm uniforms.
6	   Mặc định 0 = không đổi gì; chỉ weather/index.ts ghi vào.
7	   Gió (GĐ4): uWindDir = hướng gió thổi tới (cos, sin) trên mặt XZ; biên độ lắc ĐÃ nhân hệ số phóng đại (m): uSwayTp (hanger TP),
8	   uSwayTtl (dây văng TTL, đường cong mưa–gió), uSwaySh (dây văng Cầu sông Hàn); uTreeLean / uTreeSway: độ nghiêng tĩnh / dao động tán cây (m dịch trên mỗi m cao). */
9	export const weatherU = {
