        l1: 0.28, l2: 0.26, dU: new THREE.Vector3(1, 0, 0), nU: new THREE.Vector3(0, 0, 1), dF: new THREE.Vector3(1, 0, 0), nF: new THREE.Vector3(0, 0, 1),
